  catch (const char* p)        { std::puts("pointer"); }
}

#include <cstdio>
#include <stdexcept>

struct Member { Member() { throw std::runtime_error("m"); } };

struct Holder {
  Member m;
  Holder() try : m() {
  } catch (const std::exception&) {
    std::puts("handler");
  }
};

int main() {
  try { Holder h; std::puts("built"); }
  catch (const std::exception&) { std::puts("outer"); }
}

#include <cstdio>

struct Bad {
  ~Bad() noexcept(false) { throw 2; }
};

int main() {
  try {
    Bad b;
    throw 1;
  } catch (int i) {
    std::printf("caught %d\n", i);
  }
}

